python3 - <<'PY'
p='src/types/checker/builtin_spl_classes/filesystem.rs'
s=open(p).read()
old = """/// Builds the read that both `fgets()` and `fscanf()` perform, into `$line`.
///
/// A read that comes back `false` becomes `""`. php's own reader answers the EMPTY STRING for
/// the read that first reaches end of file — measured on `php -n` 8.5.6, `fgets()` on
/// `"a\\nbb\\n"` gives `'a\\n'`, `'bb\\n'`, then `''`, and only the call AFTER that one fails. The
/// `false` this backend used to return is not a value php ever produces here.
/// The `(string)` cast is what makes `$line` a STRING rather than `string|false`, and it is
/// also php's own answer: `(string) false` is `""`. Keeping the union instead left `fscanf()`
/// handing a boxed Mixed to `sscanf()`'s declared `string` parameter."""
new = """/// Builds the read that both `fgets()` and `fscanf()` perform, into `$line`.
///
/// A read that comes back `false` becomes `""`. php's own reader answers the EMPTY STRING for
/// the read that first reaches end of file — measured on `php -n` 8.5.6, `fgets()` on
/// `"a\\nbb\\n"` gives `'a\\n'`, `'bb\\n'`, then `''`, and only the call AFTER that one fails. The
/// `false` this backend used to return is not a value php ever produces here.
///
/// The `(string)` cast carries that rule AND the representation: it makes `$line` a STRING
/// rather than `string|false`, and `(string) false` is `""` — php's own answer. Keeping the
/// union instead left `fscanf()` handing a boxed Mixed to `sscanf()`'s declared `string`
/// parameter."""
assert s.count(old)==1
s=s.replace(old,new)
old2 = """/// `php -n` 8.5.6 throws `RuntimeException: Cannot read from file <path>` — the path as the
/// constructor received it — from `fgets()`, `fscanf()` and `getCurrentLine()` once `feof()`
/// holds. `feof()` only becomes true after a read has hit the end, which is why the empty-string
/// read above happens FIRST and this guard fires on the call after it."""
new2 = """/// `php -n` 8.5.6 throws `RuntimeException: Cannot read from file <path>` — the path as the
/// constructor received it — from `fgets()` and `fscanf()` once `feof()` holds. `feof()` only
/// becomes true after a read has hit the end, which is why the empty-string read above happens
/// FIRST and this guard fires on the call after it."""
assert s.count(old2)==1
s=s.replace(old2,new2)
open(p,'w').write(s)
print('docs tidied')
